var (
	n      int
	m      int
	result int
)

func in() {
	fmt.Scanf("%d %d\n", &n, &m)
}

func out() {
	fmt.Println(result)
}

func run() {
	var remain int = n
	var d int = 1
	for ; remain > 0; d++ {
		if d%m != 0 {
			remain--
		}
	}
	result = d - 1
}

func main() {
	in()
	run()
	out()
}
